head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp = js_market;
scwin.gAcptNo;
scwin.vScrenID = 'ULDSTF16514.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// 공시일자, 팀, 담당자 세팅
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    //dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_FileList.insertRow();
    //dts_Master.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Master.insertRow();

    //  기간 from~ to  셋팅(공시일자)
    /**
    vCurDate = cGetToday("yyyymmdd");	
    edt_SDATE.text = cGetMinusYear(vCurDate,1) ; 	// 1년전 날짜
    edt_EDATE.text =vCurDate;	// 현재날짜
    setObjectValue(cmb_PeriodTp, '1');
    */
    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
};


// 공시팀 전체 목록에 추가
scwin.fn_addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM');
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    for (var i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE"));
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE"));
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};
scwin.getDisclsEduRnd = function(gubun) {
    dts_EduCrsNm.DataID = "/DisclsEduaction.do?method=getDisclsEduRnd" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R" + "&DISCLS_EDU_APCT_TP_CD=" + gubun;
    dts_EduCrsNm.Reset();
};


// 시장구분 라디오버튼
scwin.fn_Init = function() {
    $c.stf.showObj(txb_TotalCnt, false); // 총건수 

    if (scwin.gLdMktTp != '2') {
        scwin.gLdMktTp = '1';
    }
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);

    // 콘트롤 잠그기
    rdo_MKT_ID.setDisabled(true);
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2') {
        $c.stf.showObj(panel_mkt, false);
    }
    if (scwin.gLdMktTp == '1') {
        cmb_EduApctTpCd.CBData = "^--,11^[유가]공시책임자,12^[유가]공시담당자";
    } else if (scwin.gLdMktTp == '2') {
        cmb_EduApctTpCd.CBData = "^--,1^[코스닥]공시책임자,2^[코스닥]공시담당자";
    } else {
        cmb_EduApctTpCd.CBData = "^--,11^[유가]공시책임자,12^[유가]공시담당자,1^[코스닥]공시책임자,2^[코스닥]공시담당자";
    }
};



//조회 버튼
scwin.fn_Search = function() {
    var flag = $c.stf.getObjectValue(rdo_MKT_ID);
    if (flag == "") {
        $c.win.alert("[시장구분]을 선택하세요.");
        rdo_MKT_ID.focus();
        return;
    } else {
        var discls_edu_crs_nm = $c.stf.getObjectValue(cmb_EduCrsNm);
        if (discls_edu_crs_nm == '') {
            $c.win.alert("교육회차를 선택하여 주세요.");
            return;
        } else {
            $c.cm.ShowWin(grd_Grid);
            var url = "/DisclsEduaction.do?method=listDisclsEduCost";
            url += "&DISCLS_EDU_APPL_SEQ=" + discls_edu_crs_nm;
            url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp; //법인코드
            url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD); //법인코드
            url += "&DISCLS_EDU_APCT_TP_CD=" + $c.cp.valueOfIndex(cmb_EduApctTpCd, "VALUE", cmb_EduApctTpCd.getSelectedIndex());
            url += "&PAY_PROCS_STAT_CD=" + $c.stf.getObjectValue(cmb_PAY_PROCS_STAT_CD);
            url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
            url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
            url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EmpList); //담당자
            url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_TeamList); //팀(부서코드)
            url += "&SCREN_ID=" + scwin.vScrenID;
            url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
            dts_Grid.DataID = encodeURI(url);
            dts_Grid.Reset();
        }
    }
};
scwin.fn_SelectAttach = function() {
    if (file.getValue() == "") return;
    txb_ATTACH_FILE_NM.setValue(file.getValue());
    dts_FileList.setCellData(1, "fileInfo", file.getValue());
    dts_FileList.setCellData(1, "fileUrl", file.getValue());
    dts_FileList.setCellData(1, "seq", $c.stf.getObjectValue(cmb_EduCrsNm));
    dts_FileList.setCellData(1, "disclsEduApctTpCd", $c.cp.valueOfIndex(cmb_EduApctTpCd, "VALUE", cmb_EduApctTpCd.getSelectedIndex()));
};
scwin.fn_ExcelUpload = function() {
    var file_nm = file.getValue();
    var suffix = file_nm.substring(file_nm.lastIndexOf(".") + 1);
    if ($c.stf.getObjectValue(cmb_EduCrsNm) == '') {
        $c.win.alert("교육회차를 선택하여 주세요.");
        return;
    }
    if (!(suffix == 'xls' || suffix == 'xlsx')) {
        $c.win.alert("확장자 'xls','xlsx' 만 가능합니다.");
        return;
    }
    var res = window.confirm("[" + $c.cp.valueOfIndex(cmb_EduCrsNm, "TEXT", cmb_EduCrsNm.getSelectedIndex()) + "]에 엑셀자료를 업로드 하시겠습니까?");
    if (res) {
        LastJob = "저장";
        trs_Save.Action = "/DisclsEduaction.do?method=registerExcelUpload" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pFile=dts_FileList)";
        trs_Save.post();
    }
};
scwin.fn_save = function() {
    if (window.confirm("저장하겠습니까?")) {
        var url = "/DisclsEduaction.do?method=saveDisclsEduCost" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_gridSave.Action = url;
        trs_gridSave.KeyName = "toinb_dataid4";
        trs_gridSave.KeyValue = "JSP(I:pInput=dts_Grid)";
        trs_gridSave.Post();
    }
};
scwin.fn_checkNum = function(row, colid, data) {
    var num = dts_Grid.getCellData(row, colid);
    num = num.replace(/\,|\(|\)/g, '');
    num = num.replace(/\s/g, '');
    dts_Grid.setCellData(row, colid, num);
    if (isNaN(dts_Grid.getCellData(row, colid))) {
        $c.win.alert("올바른 숫자형식으로 값을 입력해주세요.");
        grd_Grid.focus();
    }
};
scwin.fn_checkDate = function(row, colid, data) {
    var num = dts_Grid.getCellData(row, colid);
    num = num.replace(/\.|\(|\)/g, '');
    num = num.replace(/\s/g, '');
    dts_Grid.setCellData(row, colid, num);
    if (num.length != 8 && num.length != 0) {
        $c.win.alert("올바른 날자를 입력해주세요.");
        grd_Grid.focus();
    }
};
scwin.fn_allUpdate = function() {
    var val = $c.cp.valueOfIndex(cmb_update, "VALUE", cmb_update.getSelectedIndex());
    var column = '';
    var columnValue = '';
    if (val == '1') {
        column = 'PAY_PROCS_STAT_CD';
        getCellData = 'Y';
    } else if (val == '2') {
        column = 'PAY_PROCS_STAT_CD';
        getCellData = 'N';
    } else if (val == '3') {
        column = 'PAY_PROCS_STAT_CD';
        getCellData = 'D';
    } else if (val == '4') {
        column = 'DISCLS_EDU_ATTEND_YN';
        getCellData = 'Y';
    } else if (val == '5') {
        column = 'DISCLS_EDU_ATTEND_YN';
        getCellData = 'N';
    }
    if (val != '') {
        if (dts_Grid.getTotalRow() == 0) {
            $c.win.alert("업데이트 대상이  없습니다.");
            $c.stf.setObjectValue(cmb_update, '');
            return;
        }
        var gCnt = 0;
        var gStat;
        grd_Grid.Redraw = false;
        for (var k = 1; k <= dts_Grid.getTotalRow(); k++) {
            //gStat = dts_Grid.RowStatus(k);
            dts_Grid.setCellData(k, column, getCellData);
        }
        grd_Grid.Redraw = true;
    }
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE); //공시일자-종료일 이미지 버튼 클릭 시 달력 팝업

};
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE); //공시일자-시작일 이미지 버튼 클릭 시 달력 팝업

};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    if (vTp == '0') {
        $c.stf.setObjectValue(edt_SDATE, '');
        $c.stf.setObjectValue(edt_EDATE, '');
    } else {
        $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE); //기간선택 콤보박스

    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.btn_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM); // 법인명 검색 팝업

};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.dts_dts_EduCrsNm_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "" || scwin.gDepCd == "UPTEAM") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "UPTEAM" ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.cmb_EduApctTpCd_OnSelChange = function() {
    gubun = $c.cp.valueOfIndex(cmb_EduApctTpCd, "VALUE", cmb_EduApctTpCd.getSelectedIndex());
    //alert("gubun : " + gubun);
    if (gubun != '') {
        scwin.getDisclsEduRnd(gubun);
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search(); //조회 버튼

};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid); //조회완료시 LOADING 이미지 종료
    txb_TotalCnt.setValue("총건수 : " + rowcount);
};
scwin.file_OnClick = function() {
    scwin.fn_SelectAttach();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_ExcelUpload();
};
scwin.btn_Modify_onclick = function() {
    scwin.fn_save();
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    var msg = $c.stf.getMessageParam("MSG-A001", LastJob);
    $c.win.alert(msg);
    dts_FileList.removeAll();
    dts_FileList.insertRow();
    $c.stf.setObjectValue(txb_ATTACH_FILE_NM, '');
    scwin.fn_Search();
};
scwin.trs_gridSave_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_gridSave_OnSuccess = function() {
    var msg = $c.stf.getMessageParam("MSG-A001", "저장");
    $c.win.alert(msg);
};
scwin.grd_Grid_OnExit = function(row, colid, olddata) {
    if (colid == "DISCLS_EDU_APPL_AMT") {
        scwin.fn_checkNum(row, colid, olddata);
    }
    if (colid == "DISCLS_EDU_COST_DEPO_DD") {
        scwin.fn_checkDate(row, colid, olddata);
    }
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    value.setValue(dts_Grid.getCellData(row, colid));
    if (isNaN(value) && (colid == 'DISCLS_EDU_APPL_AMT' || colid == 'DISCLS_EDU_COST_DEPO_DD')) {
        return false;
    } else if (colid == 'DISCLS_EDU_COST_DEPO_DD' && !(value.length == 0 || value.length == 8)) {
        return false;
    } else {
        return true;
    }
};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '' || scwin.gDepCd == 'UPTEAM') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 
    if (scwin.gDepCd != '' && scwin.gDepCd != 'UPTEAM') {
        cmb_EmpList.trigger("onclick");
    }
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34') {
        $c.stf.CopyDataSet(dts_dep, dts_dep1);
        scwin.fn_addDsclTeamAll(rowcount);
        $c.stf.setObjectValue(cmb_TeamList, 'UPTEAM');
    }
};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "" || scwin.gDepCd == "UPTEAM") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "UPTEAM" ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.cmb_update_OnSelChange = function() {
    scwin.fn_allUpdate();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM); //법인코드 및 법인명(회사명) 관련
    Grd_com_isur.style.zIndex = 30;
    scwin.fn_SetCode(); //공시일자(from~to)
    scwin.fn_Init(); //시장구분

};
